'use strict';
// Obsidian integration. An Obsidian vault is just a folder of Markdown files, so Shelf reads
// and writes .md files inside <vault>/<folder> (default "Shelf"):
//
//   Shelf/Books/<Title>.md   one note per book: properties (frontmatter) + a "## Notes" section
//   Shelf/Notes/<Title>.md   free-form notes
//   Shelf/Quotes.md          your saved quotes, regenerated by Shelf
//
// The files are the source of truth, so edits made in Obsidian show up in Shelf and vice versa.
// Each note entry Shelf writes carries a hidden Obsidian comment (%% shelf id=… %%) so it can be
// edited or removed later; entries you write yourself in Obsidian are listed too.

const fs = require('fs');
const fsp = fs.promises;
const path = require('path');
const crypto = require('crypto');

function createVault({ dir, folder = 'Shelf', name = '' }) {
  const root = path.resolve(dir);
  const base = path.join(root, folder);
  const rel = (abs) => path.relative(root, abs).split(path.sep).join('/');

  // Resolve a vault-relative path, refusing anything outside the Shelf folder.
  function resolve(relPath) {
    const clean = String(relPath || '').replace(/\\/g, '/').replace(/^\/+/, '');
    const abs = path.resolve(root, clean);
    if (!(abs === base || abs.startsWith(base + path.sep)) || !abs.toLowerCase().endsWith('.md')) {
      throw Object.assign(new Error('Notes must be .md files inside the Shelf folder'), { status: 400 });
    }
    return abs;
  }

  const safeName = (s) => (String(s || '').replace(/[\\/:*?"<>|#^[\]\u0000-\u001f]/g, '').replace(/\s+/g, ' ').trim().slice(0, 120) || 'Untitled');

  async function write(abs, content) {
    await fsp.mkdir(path.dirname(abs), { recursive: true });
    const tmp = `${abs}.${crypto.randomBytes(4).toString('hex')}.tmp`;
    await fsp.writeFile(tmp, content);
    await fsp.rename(tmp, abs);
  }

  async function read(abs) {
    try { return await fsp.readFile(abs, 'utf8'); } catch (err) { if (err.code === 'ENOENT') return null; throw err; }
  }

  async function unique(dirAbs, title) {
    let abs = path.join(dirAbs, `${safeName(title)}.md`);
    for (let n = 2; fs.existsSync(abs); n++) abs = path.join(dirAbs, `${safeName(title)} ${n}.md`);
    return abs;
  }

  // ---------- frontmatter (simple line-based YAML; only touches the keys Shelf owns) ----------

  const yamlValue = (v) => (typeof v === 'number' ? String(v) : JSON.stringify(String(v)));

  function setProps(text, props) {
    const m = /^---\n([\s\S]*?)\n---\n?/.exec(text);
    const lines = m ? m[1].split('\n') : [];
    for (const [key, value] of Object.entries(props)) {
      const line = `${key}: ${yamlValue(value)}`;
      const i = lines.findIndex((l) => l.startsWith(`${key}:`));
      if (i >= 0) lines[i] = line;
      else lines.push(line);
    }
    const body = m ? text.slice(m[0].length) : text;
    return `---\n${lines.join('\n')}\n---\n${body}`;
  }

  function getProp(text, key) {
    const m = /^---\n([\s\S]*?)\n---/.exec(text);
    if (!m) return null;
    const line = m[1].split('\n').find((l) => l.startsWith(`${key}:`));
    if (!line) return null;
    const raw = line.slice(key.length + 1).trim();
    try { return raw.startsWith('"') ? JSON.parse(raw) : raw; } catch { return raw.replace(/^['"]|['"]$/g, ''); }
  }

  // ---------- note entries inside "## Notes" ----------

  function notesSection(text) {
    const m = /^## Notes[ \t]*$/m.exec(text);
    if (!m) return null;
    const start = m.index + m[0].length;
    const next = /^## /m.exec(text.slice(start));
    return { start, end: next ? start + next.index : text.length };
  }

  function parseEntries(text) {
    const sec = notesSection(text);
    if (!sec) return [];
    const body = text.slice(sec.start, sec.end);
    const out = [];
    const re = /^### .*$/gm;
    const heads = [...body.matchAll(re)];
    heads.forEach((h, i) => {
      const from = sec.start + h.index;
      const to = i + 1 < heads.length ? sec.start + heads[i + 1].index : sec.end;
      const chunk = text.slice(from, to);
      const lines = chunk.split('\n');
      const heading = lines.shift().slice(4).trim();
      let meta = {};
      if (lines[0] && /^%%\s*shelf\b/.test(lines[0])) {
        for (const [, k, v] of lines.shift().matchAll(/(\w+)=(\S+)/g)) meta[k] = v;
      }
      const quote = [];
      while (lines.length && (lines[0].startsWith('>') || (!quote.length && lines[0].trim() === ''))) {
        const l = lines.shift();
        if (l.startsWith('>')) quote.push(l.replace(/^>\s?/, ''));
      }
      const id = meta.id || `h${crypto.createHash('sha1').update(chunk).digest('hex').slice(0, 10)}`;
      out.push({
        id,
        heading,
        chapter: meta.chapter != null ? Number(meta.chapter) : null,
        at: meta.at || null,
        quote: quote.join('\n').trim(),
        body: lines.join('\n').trim(),
        from,
        to,
      });
    });
    return out;
  }

  function formatEntry({ id, heading, chapter, at, quote, body }) {
    const meta = `%% shelf id=${id}${chapter != null ? ` chapter=${chapter}` : ''} at=${at} %%`;
    const q = quote ? `${quote.split('\n').map((l) => `> ${l}`).join('\n')}\n\n` : '';
    return `### ${heading}\n${meta}\n${q}${body ? `${body.trim()}\n` : ''}\n`;
  }

  // ---------- book notes ----------

  const bookPaths = new Map(); // bookId -> absolute path (cache)

  async function findBookNote(book) {
    const cached = bookPaths.get(book.id);
    if (cached && fs.existsSync(cached)) return cached;
    // The note may have been renamed or moved in Obsidian: look for its shelf-id property.
    const files = await listFiles(base);
    for (const abs of files) {
      const head = (await read(abs) || '').slice(0, 800);
      if (getProp(head, 'shelf-id') === book.id) { bookPaths.set(book.id, abs); return abs; }
    }
    return null;
  }

  function bookProps(book, extra = {}) {
    return {
      title: book.title,
      author: book.author || '',
      type: book.kind === 'epub' ? 'novel' : 'manga',
      'shelf-id': book.id,
      ...extra,
    };
  }

  async function ensureBookNote(book, extra) {
    let abs = await findBookNote(book);
    if (abs) return abs;
    abs = await unique(path.join(base, 'Books'), book.title);
    const template = `---\ntags:\n  - shelf\n  - ${book.kind === 'epub' ? 'book' : 'manga'}\n---\n`
      + `# ${book.title}\n${book.author ? `*by ${book.author}*\n` : ''}\n## Notes\n`;
    await write(abs, setProps(template, bookProps(book, extra)));
    bookPaths.set(book.id, abs);
    return abs;
  }

  async function bookNotes(book) {
    const abs = await findBookNote(book);
    if (!abs) return { path: null, entries: [] };
    const text = await read(abs);
    return { path: rel(abs), entries: parseEntries(text || '').map(({ from, to, ...e }) => e) };
  }

  async function addBookNote(book, { chapter, chapterLabel, quote, body, kind }, extra) {
    const abs = await ensureBookNote(book, extra);
    let text = (await read(abs)) || '';
    const at = new Date();
    const when = at.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    const entry = {
      id: crypto.randomBytes(4).toString('hex'),
      heading: `${kind === 'quote' ? 'Quote · ' : ''}${chapterLabel || (chapter != null ? `Chapter ${chapter + 1}` : 'Note')} · ${when}`,
      chapter: Number.isInteger(chapter) ? chapter : null,
      at: at.toISOString(),
      quote: (quote || '').trim(),
      body: (body || '').trim(),
    };
    let sec = notesSection(text);
    if (!sec) { text = `${text.replace(/\s*$/, '\n')}\n## Notes\n`; sec = notesSection(text); }
    const before = text.slice(0, sec.end).replace(/\s*$/, '\n\n');
    text = before + formatEntry(entry) + text.slice(sec.end).replace(/^\s*/, sec.end < text.length ? '\n' : '');
    if (extra) text = setProps(text, extra);
    await write(abs, text);
    return { path: rel(abs), entry };
  }

  async function editBookNote(book, id, { quote, body }) {
    const abs = await findBookNote(book);
    const text = abs && (await read(abs));
    const entry = text && parseEntries(text).find((e) => e.id === id);
    if (!entry) throw Object.assign(new Error('Note not found (was it changed in Obsidian?)'), { status: 404 });
    const next = formatEntry({
      ...entry,
      id: entry.id.startsWith('h') ? crypto.randomBytes(4).toString('hex') : entry.id,
      at: entry.at || new Date().toISOString(),
      quote: quote != null ? quote : entry.quote,
      body: body != null ? body : entry.body,
    });
    await write(abs, text.slice(0, entry.from) + next + text.slice(entry.to).replace(/^\n+/, ''));
  }

  async function deleteBookNote(book, id) {
    const abs = await findBookNote(book);
    const text = abs && (await read(abs));
    const entry = text && parseEntries(text).find((e) => e.id === id);
    if (!entry) throw Object.assign(new Error('Note not found (was it changed in Obsidian?)'), { status: 404 });
    await write(abs, text.slice(0, entry.from) + text.slice(entry.to).replace(/^\n+/, ''));
  }

  // Keep the reading progress property up to date (only for books that already have a note).
  const lastTouch = new Map();
  async function touchProgress(book, props, force = false) {
    const now = Date.now();
    if (!force && now - (lastTouch.get(book.id) || 0) < 5 * 60 * 1000) return;
    lastTouch.set(book.id, now);
    const abs = await findBookNote(book);
    const text = abs && (await read(abs));
    if (text) await write(abs, setProps(text, props));
  }

  // ---------- free notes + listing ----------

  async function listFiles(dirAbs) {
    const out = [];
    let entries;
    try { entries = await fsp.readdir(dirAbs, { withFileTypes: true }); } catch { return out; }
    for (const ent of entries) {
      if (ent.name.startsWith('.')) continue;
      const abs = path.join(dirAbs, ent.name);
      if (ent.isDirectory()) out.push(...(await listFiles(abs)));
      else if (ent.isFile() && ent.name.toLowerCase().endsWith('.md')) out.push(abs);
    }
    return out;
  }

  async function list() {
    const files = await listFiles(base);
    const out = [];
    for (const abs of files) {
      const st = await fsp.stat(abs);
      const head = ((await read(abs)) || '').slice(0, 800);
      const r = rel(abs);
      out.push({
        path: r,
        title: path.basename(abs, '.md'),
        kind: getProp(head, 'shelf-id') ? 'book' : r === `${folder}/Quotes.md` ? 'quotes' : 'note',
        bookId: getProp(head, 'shelf-id') || null,
        mtime: st.mtimeMs,
        size: st.size,
      });
    }
    return out.sort((a, b) => b.mtime - a.mtime);
  }

  async function getFile(relPath) {
    const abs = resolve(relPath);
    const content = await read(abs);
    if (content == null) throw Object.assign(new Error('Note not found'), { status: 404 });
    return { path: rel(abs), content, mtime: (await fsp.stat(abs)).mtimeMs };
  }

  // Save a whole file. If it changed on disk since `baseMtime` (e.g. edited in Obsidian), refuse.
  async function putFile(relPath, content, baseMtime) {
    const abs = resolve(relPath);
    if (baseMtime && fs.existsSync(abs)) {
      const st = await fsp.stat(abs);
      if (st.mtimeMs > baseMtime + 1) {
        throw Object.assign(new Error('This note was changed somewhere else (maybe in Obsidian). Reload it first.'), { status: 409 });
      }
    }
    await write(abs, content);
    return { path: rel(abs), mtime: (await fsp.stat(abs)).mtimeMs };
  }

  async function newNote(title, content = '') {
    const abs = await unique(path.join(base, 'Notes'), title || 'Untitled');
    const t = path.basename(abs, '.md');
    await write(abs, content || `---\ntags:\n  - shelf\ncreated: ${new Date().toISOString().slice(0, 10)}\n---\n# ${t}\n\n`);
    return { path: rel(abs), mtime: (await fsp.stat(abs)).mtimeMs };
  }

  async function removeFile(relPath) {
    const abs = resolve(relPath);
    await fsp.rm(abs, { force: true });
    for (const [id, p] of bookPaths) if (p === abs) bookPaths.delete(id);
  }

  // ---------- Quotes.md ----------

  async function writeQuotes(quotes, bookNoteFor) {
    const groups = { anime: 'Anime', quote: 'Quotes', book: 'From my books' };
    let md = '---\ntags:\n  - shelf\n  - quotes\n---\n# Saved quotes\n\n'
      + '*Kept in sync by Shelf: save or remove quotes in Shelf. Edits made here are overwritten.*\n';
    for (const [kind, label] of Object.entries(groups)) {
      const list = quotes.filter((q) => q.kind === kind);
      if (!list.length) continue;
      md += `\n## ${label}\n`;
      for (const q of list) {
        const link = q.bookId && bookNoteFor(q.bookId);
        const source = link ? `[[${link.replace(/\.md$/, '')}|${q.from || 'book'}]]` : [q.by, q.from].filter(Boolean).join(', ');
        md += `\n> ${q.text.replace(/\n/g, '\n> ')}\n${source ? `> — ${source}\n` : ''}`;
      }
    }
    await write(path.join(base, 'Quotes.md'), md);
  }

  const relBookPath = (id) => (bookPaths.has(id) ? rel(bookPaths.get(id)) : null);

  return {
    root, folder, name, base,
    info: () => ({ folder, vaultName: name, location: root }),
    list, getFile, putFile, newNote, removeFile,
    bookNotes, addBookNote, editBookNote, deleteBookNote, touchProgress, findBookNote,
    writeQuotes, relBookPath,
    parseEntries, setProps, getProp, // exported for tests
  };
}

module.exports = { createVault };
